using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class ConcernDivisionWorkflowService(IConcernDivisionWorkflowRepository repository,ICurrentUserService currentUser):IConcernDivisionWorkflowService{
 public Task<IReadOnlyList<ConcernDivisionPendingDto>>GetPendingAsync(CancellationToken c)=>repository.GetPendingAsync(currentUser.EmployeeId,c);public Task<RequisitionDetailDto?>GetDetailAsync(long id,CancellationToken c)=>repository.GetDetailAsync(Valid(id),currentUser.EmployeeId,c);public Task<ConcernDivisionReviewContextDto?>GetContextAsync(long id,CancellationToken c)=>repository.GetContextAsync(Valid(id),currentUser.EmployeeId,c);public Task<StoredProcedureResult?>VerifyCompleteAsync(long id,string?m,CancellationToken c){Length(m);return repository.VerifyCompleteAsync(Valid(id),currentUser.EmployeeId,m?.Trim(),c);}public Task<StoredProcedureResult?>ForwardAuthorityAsync(long id,string?m,CancellationToken c){Length(m);return repository.ForwardAuthorityAsync(Valid(id),currentUser.EmployeeId,m?.Trim(),c);}public Task<StoredProcedureResult?>ReturnAsync(long id,string?m,CancellationToken c)=>repository.ReturnAsync(Valid(id),currentUser.EmployeeId,Required(m),c);public Task<StoredProcedureResult?>NotRecommendAsync(long id,string?m,CancellationToken c)=>repository.NotRecommendAsync(Valid(id),currentUser.EmployeeId,Required(m),c);private static long Valid(long id){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));return id;}private static string Required(string?m){if(string.IsNullOrWhiteSpace(m))throw new ArgumentException("Remarks are required for return and not-recommend actions.");Length(m);return m.Trim();}private static void Length(string?m){if(m?.Length>2000)throw new ArgumentException("Remarks cannot exceed 2000 characters.");}}
